def parse_duration(s):
    if not s:
        raise ValueError("Input string is empty")

    duration_map = {
        'd': 'days',
        'h': 'hours',
        'm': 'minutes',
        's': 'seconds'
    }

    # Check for invalid input
    for char in s:
        if char not in duration_map:
            raise ValueError(f"Unknown unit: {char}")

    # Check for missing numbers
    for unit, unit_name in duration_map.items():
        if unit_name not in s and unit not in s:
            raise ValueError(f"Unit {unit} without a number")

    # Check for numbers without units
    for char in s:
        if char.isdigit() and (s[s.index(char) - 1] not in duration_map and s[s.index(char) + 1] not in duration_map):
            raise ValueError(f"Number without a unit: {char}")

    # Check for out of order units
    if 'd' in s and 'h' in s and 'd' > 'h':
        raise ValueError("Units out of order: days come after hours")
    if 'h' in s and 'm' in s and 'h' > 'm':
        raise ValueError("Units out of order: hours come after minutes")
    if 'm' in s and 's' in s and 'm' > 's':
        raise ValueError("Units out of order: minutes come after seconds")

    # Check for repeated units
    if len(set(duration_map.keys())) != len(duration_map):
        raise ValueError("Repeated units")

    # Parse the duration
    duration = 0
    for unit, unit_name in duration_map.items():
        if unit in s:
            num = int(s.split(unit)[0])
            if num < 0:
                raise ValueError(f"Negative value for {unit_name}: {num}")
            if unit_name == 'seconds':
                duration += num
            elif unit_name == 'minutes':
                duration += num * 60
            elif unit_name == 'hours':
                duration += num * 3600
            elif unit_name == 'days':
                duration += num * 86400

    return duration
