        if unit in units:
            if value not in parsed:
                parsed[value] = int(units.split(unit)[0])
                if not parsed[value]:
                    raise ValueError(f"Unit {unit} without a number")
                units = units.split(unit)[1]
            else:
                raise ValueError(f"Repeated unit {unit}")
        else:
            parsed[value] = 0

    if units:
        raise ValueError(f"Unknown unit: {units}")

    total_seconds = parsed['seconds'] + parsed['minutes'] * 60 + parsed['hours'] * 3600 + parsed['days'] * 86400
    return total_seconds
