def split_fields(line):
    """
    Splits a CSV line on commas while honouring double-quoted fields.

    Commas inside quotes do not split, a doubled quote ("") inside a quoted field is a literal quote,
    and the surrounding quotes are removed. An empty line returns [''].

    :param line: The CSV line to split.
    :return: A list of fields.
    """
    if not line:
        return ['']

    fields = []
    field = ''
    in_quote = False
    escape_next = False

    for char in line:
        if escape_next:
            field += char
            escape_next = False
        elif char == '"':
            if in_quote:
                field += char
            else:
                in_quote = True
        elif in_quote and char == ',':
            fields.append(field[1:-1])  # Remove surrounding quotes
            field = ''
            in_quote = False
        elif in_quote and char == '"':
            field += char
        elif not in_quote and char == ',':
            fields.append(field)
            field = ''
        else:
            field += char

    if field:
        fields.append(field[1:-1] if in_quote else field)  # Remove surrounding quotes if in quote mode

    return fields
