def shortest(graph, start, goal):
    if start == goal:
        return (0, [start])

    from heapq import heappop, heappush

    # Priority queue, storing (cost, node)
    queue = [(0, start)]
    # Dictionary to store the minimum cost to reach each node
    costs = {node: float('inf') for node in graph}
    costs[start] = 0
    # Dictionary to store the path to each node
    prev = {node: None for node in graph}

    while queue:
        current_cost, current_node = heappop(queue)

        if current_node == goal:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = prev[current_node]
            path.reverse()
            return (current_cost, path)

        for neighbor, weight in graph[current_node]:
            cost = current_cost + weight
            if cost < costs[neighbor]:
                costs[neighbor] = cost
                prev[neighbor] = current_node
                heappush(queue, (cost, neighbor))

    return (None, [])
